def seed_product_cards(apps, schema_editor):
    ProductCard = apps.get_model('myapp', 'ProductCard')
    if ProductCard.objects.exists():
        return
    dest_dir = os.path.join(settings.MEDIA_ROOT, 'products_home')
    os.makedirs(dest_dir, exist_ok=True)
    for order, card in enumerate(_SEED_CARDS):
        filename = card['image']
        src = os.path.join(_SOURCE_STATIC_DIR, filename)
        if not os.path.isfile(src):
            continue
        dest = os.path.join(dest_dir, filename)
        if not os.path.isfile(dest):
            shutil.copyfile(src, dest)
        ProductCard.objects.create(
            image=f'products_home/{filename}',
            badge_text=card['badge_text'],
            title=card['title'],
            subtitle=card['subtitle'],
            price_amount=card['price_amount'],
            price_suffix=card['price_suffix'],
            features=card['features'],
            cta_text=card['cta_text'],
            accent_color=card['accent_color'],
            order=order,
        )


